public abstract record Command
{
    public abstract JsonNode ToJson();

    public static Command FromJson(JsonNode? value)
    {
        var obj = Wire.Object(value);
        if (Wire.TagIs(obj, "setPop")) return SetPop.FromJson(value);
        if (Wire.TagIs(obj, "ping")) return Ping.FromJson(value);
        if (Wire.TagIs(obj, "setSource")) return SetSource.FromJson(value);
        if (Wire.TagIs(obj, "uploaded")) return Uploaded.FromJson(value);
        if (Wire.TagIs(obj, "stopSource")) return StopSource.FromJson(value);
        if (Wire.TagIs(obj, "getGraph")) return GetGraph.FromJson(value);
        if (Wire.TagIs(obj, "quit")) return Quit.FromJson(value);
        throw new FormatException("no variant matches");
    }

    public static Command Decode(JsonNode? value)
    {
        var tree = Wire.Tree(value, out var unicode);
        try
        {
            if (!unicode) throw new FormatException("a string holds a lone surrogate");
            return FromJson(tree);
        }
        catch (FormatException)
        {
            return new UnknownCommand(tree is JsonObject obj ? (JsonObject)obj.DeepClone() : new JsonObject());
        }
    }
}

public sealed record UnknownCommand(JsonObject Raw) : Command
{
    public override JsonNode ToJson() => Raw.DeepClone();
}


